// pass `loadTasks` to point it elsewhere or to stub it in tests.
async function defaultLoadTasks(signal) {
  const res = await fetch('/api/tasks', { signal });
  if (!res.ok) throw new Error(`Request failed: ${res.status}`);
  return res.json();
}

